md=[];ht=[]
def h(s,level=2):md.append('#'*level+' '+s);ht.append(f'<h{level}>'+html.escape(s)+f'</h{level}>')
def p(s):md.append(s);ht.append('<p>'+html.escape(s)+'</p>')
def table(cols,rows):
 md.append('| '+' | '.join(cols)+' |\n| '+' | '.join(['---']*len(cols))+' |\n'+'\n'.join('| '+' | '.join(str(v).replace('|','/') for v in row)+' |' for row in rows));ht.append('<div class="tablewrap"><table><thead><tr>'+''.join('<th>'+html.escape(c)+'</th>' for c in cols)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(str(c))+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>')
def image(name,alt):md.append(f'![{alt}]({name})');ht.append('<figure><img alt="'+html.escape(alt)+'" src="data:image/png;base64,'+base64.b64encode((O/name).read_bytes()).decode()+'"></figure>')
def f(x,n=3):return '–' if not np.isfinite(x) else f'{x:.{n}f}'.replace('.',',')
def pct(x,n=2):return f(100*x,n)+' %'
def eur(x):return f'{x:,.0f}'.replace(',','.')+' €'
h('PCA, Faktor-Zustände und Kursprognosen',1);p('Historische Folgestudie · 02.11.2026 · Die Aktien-App wurde nicht verändert.')
h('Ergebnis')
p('Die vorgeschlagene gemeinsame Faktorenanalyse wurde durchgeführt. PCA, PLS, regularisierte Regressionen und ein kleiner fester nichtlinearer Vergleich wurden zeitlich vorwärts getestet. In diesem Datensatz liefert keines der Modelle einen geringeren mittleren Prognosefehler als die einfache Annahme eines erwarteten Mehrertrags von null. Ein belastbares Modell zur Vorhersage überdurchschnittlicher Kursanstiege wurde nicht gefunden.')
p('Die PCA identifiziert nachvollziehbare gemeinsame Achsen. Das sind Beschreibungen von Variation in den Eingaben; sie sind weder automatisch wesentliche Kursprädiktoren noch Belege psychologischer Ursachen. Das negative Ergebnis betrifft die vorhandenen Merkmale, die historische Großkonzern-Kohorte und die hier untersuchten Vier-/Zwölfwochen-Ziele. Es beweist keine allgemeine Unmöglichkeit von Renditeprognosen.')
h('Was aus den sieben früheren Testpaketen zusammengeführt werden konnte')
use=[('Fünfjahres-Backtest','Trades, 320 überlappende Datumstests, Kurven','Kurs-/Volumen-/ATR-Merkmale rekonstruiert; künftige Tradegewinne keine Eingaben'),('ATR-Grenzen','20 Stop-/Limit-Varianten und Ergebnisse','ATR als damaliger Risikozustand; keine Ergebnisse späterer Ausführungen als Faktor'),('12–2-Momentum','Strategievergleiche und Kurven','Historisches Momentum als Eingabe, hier exakt zwischen 252 und 42 Handelstagen'),('Wissenschaftliche Faktorstudie','Aggregierte Value-/Quality-/Investment-/Momentum-Portfolios','Marktindikatoren in gesonderter, nicht streng point-in-time-fähiger Erweiterung'),('Unabhängige Handelsregeln','Trades und Variantenkurven','Vergleichs-/Kostenannahmen und Grenzen; keine Vermischung mit Aktienmerkmalen'),('Behavioral-Studie','312 Monate primitive Signal-/Faktorportfoliorenditen','24 verzögerte Marktindikatoren im Zusatztest'),('Globales Stimmungsmodell','Historische Nachrichten-Metadaten, Kurse, Devisen','Hauptquelle für gemeinsames Aktien-Zeitpunkt-Panel; frühere Zustands- und Zukunftsspalten ausgeschlossen')]
table(['Paket','Gespeicherte Ebene','Verwendung'],use)
p('Frühere Handelsgewinne, nachträgliche Stop-Ausgänge oder Testergebnisse lassen sich nicht als damals bekannte Faktoren verwenden. Einige ältere Studien haben heute noch gelistete Firmen rückwirkend untersucht. Dieser Auswahlfehler wird durch PCA nicht behoben; ihre Trade-Ergebnisse werden nicht in das neue Trainingspanel eingespeist.')
p('Das neue Panel verwendet unverändert die vor 2019 veröffentlichte PwC-Top-100-Liste vom März 2018. 34.323 Firmen-Zeitpunkte von 100 Firmen aus 19 Ländern stehen zwischen 02.01.2019 und 24.09.2025 bereit. Daraus entstehen 19.108 Vorwärtsprognosen für 98 Firmen und 195 Testwochen; 19.094 haben eine bewertbare Vierwochen-Zielrendite. Zwei historische Unternehmensreihen enden bei ihren strukturellen Abspaltungen; über diese Grenze hinaus wird keine Nachfolgerhistorie unterstellt.')
p('44 numerische Hauptmerkmale: 18 technische Merkmale, vier Marktmerkmale, 16 Nachrichtenmerkmale und sechs festgelegte Wechselwirkungen. Firmen-/Regionskontrollen und fehlende Werte werden separat berücksichtigt. Vollständige historische firmenspezifische Bewertungs-, Bilanz-, Gewinnüberraschungs- und Analystenkonsens-Vintages fehlen. Eine heutige Kennzahl wurde nicht in die Vergangenheit kopiert. Der Versuch ist daher keine vollständige Prüfung aller jemals in der App diskutierten Fundamentalaspekte.')
h('Ziel und zeitliche Durchführung')
p('Primär vorhergesagt wird die Vierwochen-Rendite einer Aktie relativ zum zeitgleichen gleichgewichteten regionalen Aktienkorb in USD. Bei Regionen mit weniger als fünf Titeln gilt der historische globale Korb. Sekundär wird dasselbe Zwölfwochen-Ziel geprüft. Das unterscheidet Aktienauswahl mit Mehrertrag von der bloßen Vorhersage eines allgemeinen Kursanstiegs in einem steigenden Markt.')
p('Die Eingabe entspricht einem Archivmittwoch um 12:00 UTC. Alle technischen Kursmerkmale enden am vorangegangenen Dienstag. Einstieg ist frühestens der folgende Montag; Ausstieg vier bzw. zwölf Kalenderwochen später, jeweils der erste verfügbare lokale Handelstag innerhalb von vier Tagen. Die mehrtägige Verzögerung ist konservativ und prüft keine unmittelbare Intraday-Reaktion auf Meldungen.')
p('Für jedes Prognosejahr 2022, 2023, 2024 und 2025 wird das Modell neu mit expandierender Vergangenheit ab 2019 geschätzt. Nur bereits vor dem Jahreswechsel abgeschlossene Zielrenditen werden trainiert. Das gilt auch für alle Bestandteile der zugehörigen Benchmarkrendite. Die Parameterwahl erfolgt innerhalb dieses Trainingsbereichs im letzten abgeschlossenen Kalenderjahr; die davorliegenden Jahre liefern das innere Training. Kein zufälliges Zeilensplitting.')
p('Median-Ersetzung, Begrenzung auf Trainings-Perzentile 1/99, Standardisierung, Firmenkodierung und PCA/PLS werden pro Fenster neu nur aus Trainingsdaten gelernt. Die früher auf 2019–2021 geschätzten Stimmungskategorien werden nicht als Eingaben wiederverwendet. Nachrichten-Rohmerkmale und ihre rückwärts gerichteten Änderungen bleiben erhalten. Imputed Werte sind Rechenhilfen, keine behaupteten neutralen Stimmungen.')
p('Die Protokoll- und Quellcode-Hashes wurden vor Berechnung der neuen Zielkennzahlen festgehalten. Die früheren Studienergebnisse waren jedoch bereits bekannt. Dies ist daher eine explorative historische Folgestudie und keine neue intellektuell unberührte Bestätigung. Ein möglicher Erfolg hätte einen separat festgelegten oder prospektiven Prüfzeitraum gebraucht.')
h('Verglichene Modelle')
table(['Modell','Vorab festgelegte Auswahl'],[(NAMES['zero'],'Erwarteter relativer Mehrertrag = 0'),(NAMES['price_ridge'],'Preis-/Volumen-/Marktzustände inkl. rein kursbasierter Wechselwirkungen; Ridge α 1/10/100'),(NAMES['all_ridge'],'Alle 44 Merkmale, Ridge α 1/10/100'),(NAMES['elastic_net'],'Alle Merkmale, l1_ratio 0,5; α 0,0001/0,001/0,01'),(NAMES['pca_ridge'],'2/4/8/12/20 numerische PCA-Komponenten, danach Ridge α 10 plus Kontrollen'),(NAMES['pls_ridge'],'2/4/8/12 überwachte PLS-Komponenten, danach Ridge α 10 plus Kontrollen'),(NAMES['small_boosting'],'Ein fester kleiner Baumensemble-Vergleich mit sieben Blättern, 100 Iterationen, kein Architektursuchlauf')])
p('Auswahlkriterium ist ausschließlich der mittlere quadratische Fehler im inneren vergangenen Validierungsjahr. Die späteren Testrenditen werden nicht zur Komponenten-/Parameterwahl verwendet. PCA und PLS wählen in allen vier Prognosejahren zwei Komponenten. Elastic Net schrumpft an 143 von 195 Teststichtagen auf eine konstante Querschnittsprognose; an diesen Tagen liefert es keine Rangordnung für Aktien.')
h('Hauptergebnis: Prognosefehler und Rangordnung')
table(['Modell','RMSE in Rendite-Prozentpunkten','R² gegen Nullprognose','AUC für positiven Mehrertrag'],[(NAMES[m],f(100*v['rmse'],3),pct(v['r2_zero']),f(v['auc'],4)) for m,v in r['overall'].items()])
p('RMSE ist der typische quadratische Prognosefehler; kleiner ist besser. R² hier = 1 − Modell-MSE / MSE der Nullprognose. Ein negativer Wert bedeutet einen größeren Fehler als „erwarteter Mehrertrag null“. Er ist nicht mit der erklärten Eingabevarianz der PCA zu verwechseln. AUC 0,5 entspricht keiner überlegenen Rangordnung für das Vorzeichen des Mehrertrags. Alle Kandidaten liegen im Gesamttest beim R² unter null; PCA und PLS erreichen AUC 0,4966 bzw. 0,4970.')
image('prognosefehler.png','Prognosequalität gegenüber Null auf identischen Testdaten')
rows=[]
for e in r['primary_tests']:rows.append((NAMES[e['model']],NAMES[e['baseline']],pct(e['relative_loss_reduction']),f(e['p_holm'],4)))
table(['Kandidat','Vergleich','Relative MSE-Verringerung','p, Holm-korrigiert'],rows)
p('Sieben vorab definierte Vergleiche, 5.000 gepaarte zirkuläre Bootstrap-Wiederholungen über ganze Kalenderwochen in 13-Wochen-Blöcken; alle Aktien einer Woche bleiben zusammen. Sensitivität acht und 26 Wochen. Der kleine nichtlineare Vergleich schlägt die schwächere Preis-Ridge-Referenz im primären Test (p korrigiert 0,0336). Das ist kein Sieg über die Nullprognose. Bei anderen Blocklängen ist die entsprechende Mehrfachtest-Evidenz schwächer. PCA/PLS zeigen keinen belastbaren Zusatznutzen gegenüber Preis-Ridge oder Gesamt-Ridge.')
table(['Jahr','PCA: R² gegen Null','PLS: R² gegen Null','Nichtlinear: R² gegen Null'],[(y,pct(v['pca_ridge']['r2_zero']),pct(v['pls_ridge']['r2_zero']),pct(v['small_boosting']['r2_zero'])) for y,v in r['by_year'].items()])
p('Die Effekte sind über die Jahre nicht stabil. PCA und PLS bleiben in jedem Testjahr beim Fehlermaß unter der Nullprognose. Die Detailtabellen nach Region stehen in results_primary.json; keine regionale Untergruppe wird nachträglich als erfolgreicher neuer Ansatz ausgewählt.')
h('Was PCA über die Faktorenstruktur zeigt')
table(['Prognosejahr','Gewählte Komponenten','Erklärte Eingabevarianz der ersten zwei','Komponenten für mindestens 90 % Varianz'],[(y,2,pct(float(g[g.component==2].cumulative.iloc[0])),int(g[g.cumulative>=.9].component.min())) for y,g in spectrum.groupby('year')])
p('Komponente 1 beschreibt vor allem die Gegenüberstellung von Trendlage und Rückschlagsrisiko: Drawdown, Abstand zu längerfristigen Durchschnitten/Hochs, Downside-Volatilität und ATR. Komponente 2 wird von Nachrichten-/Quellenzahl, Tonstreuung und Abdeckung geprägt. Diese Muster sind im Trainingsmaterial recht stabil. Sie erklären etwa ein Drittel der Variation der 44 numerischen Eingaben. Für 90 % werden 17 Komponenten benötigt. Mehr Varianzerklärung führt nicht automatisch zu besserer Prognose; größere Komponentenanzahlen wurden im inneren Zeitfenster angeboten und nicht gewählt.')
image('pca_struktur.png','PCA-Eingabevarianz und Zusammensetzung der ersten zwei Komponenten aus Trainingsdaten')
p('Die Weglassdiagnose entfernt vorab definierte Gruppen einzeln und passt die Verarbeitung neu an, ohne die im inneren Zeitfenster gewählten Parameter nach Testerfolg zu optimieren. Dabei zeigt sich kein universell stabiler Faktorbeitrag über alle Verfahren. Nachrichten helfen beispielsweise dem eingeschränkten PCA-Modell relativ zu dessen Version ohne Nachrichten, verschlechtern aber PLS und Elastic Net in dieser Diagnose. Das ist weder ein gemeinsamer Renditevorteil noch ein Kausalnachweis. Die 28 Weglassvergleiche sind deskriptiv und wurden nicht als neue Erfolgsfamilie verwendet.')
h('Zwölf Wochen und zusätzliche Faktor-Marktindikatoren')
table(['Modell','Vier Wochen: Hauptpanel R²','Zwölf Wochen: Hauptpanel R²','Vier Wochen: erweitertes Panel R²'],[(NAMES[m],pct(r['overall'][m]['r2_zero']),pct(r12['overall'][m]['r2_zero']),pct(ext['overall'][m]['r2_zero'])) for m in ['all_ridge','elastic_net','pca_ridge','pls_ridge']])
p('Die Erweiterung ergänzt 24 letzte/einige Monate zurückliegende Portfoliorendite-Indikatoren: Momentum, Earnings Surprise, Analystenrevisionen, Announcement Return, Value, Quality und French-Faktoren. Rechnerische Verfügbarkeit: Monatsende plus 62 Kalendertage. Diese Größen sind Markt-/Faktorzustände, keine Fundamentaldaten der jeweiligen einzelnen Aktie. Da Originalveröffentlichungen und unveränderte Datenvintages fehlen, ist die Erweiterung nicht streng point-in-time-fähig. Auch sie liefert hier keinen geringeren MSE als die Nullprognose. Zwölf Wochen liefern ebenfalls keinen besseren MSE; diese Ergebnisse bleiben sekundär und werden nicht zur Wahl eines nachträglichen Gewinner-Zeithorizonts benutzt.')
h('Finanzielle Zusatzdiagnose mit Kosten')
p('Fester Vierwochen-Takt, 49 gemeinsame vollständig bewertbare Kohorten vom Signal 05.01.2022 bis 10.09.2025; keine Kohorte fehlt. Obere 20 % der Prognoseränge je Region, feste historische Regionsgewichte. Gleichstände an der Grenze werden proportional aufgeteilt; eine konstante Prognose erzeugt keine zufällige scheinbar erfolgreiche Aktienauswahl anhand der Zeilenreihenfolge.')
p('Modellkapital 10.000 EUR; aktive Positionen werden je Kohorte vollständig geschlossen und neu eröffnet. Ein Euro je Kauf und Verkauf sowie 0,1 % ungünstige Ausführung je Seite. Das ist konservativ, weil auch unverändert ausgewählte Titel erneut Kosten verursachen. Brutto und nur feste Gebühren werden zusätzlich ausgewiesen. Benchmarks werden großzügig ohne Transaktionskosten gerechnet: historischer Korb und ACWI. Die ursprüngliche kostenbelastete Rundlauf-Benchmark wird nicht als Erfolgsmaß verwendet, da viele Einzeltitel zu künstlich hohen Fixgebühren führen würden. Die nachträgliche Darstellungsprüfung ist in portfolio_evaluation_note.md dokumentiert; die primären Modelle wurden dafür nicht verändert.')
fin={x['model']:x for x in finance['candidates']}
table(['Ansatz','Endwert brutto','Endwert nur feste Gebühren','Endwert Gebühren + Slippage'],[(NAMES[m],eur(fin[m]['gross_end_eur']),eur(fin[m]['fees_end_eur']),eur(fin[m]['net_end_eur'])) for m in ['pca_ridge','pls_ridge','small_boosting']]+[('Historischer Korb',eur(fin['pca_ridge']['benchmark_gross_end_eur']),'–','–'),('ACWI',eur(fin['pca_ridge']['acwi_gross_end_eur']),'–','–')])
p('Die ausgewiesenen aktiven Beispiele bleiben mit den festgelegten Kosten unter beiden Bruttovergleichen. Einzelne Bruttoranglisten sehen besser aus als der historische Korb; das ersetzt weder die fehlende robuste Prognoseevidenz noch einen Kosten-/Risikonachweis. Elastic Net wird hier nicht als praktikables Einzelaktien-Handelsmodell dargestellt: Viele konstante Prognosen implizieren neutralen Korbbesitz; dessen Nachbildung mit zahlreichen festen Einzelordergebühren wäre keine sinnvolle ETF-Kostenannahme.')
image('handelsdiagnose.png','Modellkapital unter festen konservativen Kosten, verglichen mit Bruttobenchmarks')
p('Dies ist eine deskriptive Näherung, keine brokerfähige Ausführungssimulation: gemischte Aktiengattungen/ADRs, lokale Feiertage, FX-Referenzkurse, angenommene Bruchstücke und fehlende historische Trade-Republic-Verfügbarkeit. Keine österreichischen Steuern, kein Markteinfluss und keine wirklichen Geld-/Briefkurse. Die Gruppenwahl wurde nicht anhand dieses Kapitalpfads optimiert. Es wird kein universell bestes oder maximal erfolgversprechendes Modell behauptet.')
h('Integrität, verbleibende Grenzen und Dateien')
p('21 Integritätsprüfungen bestanden. Gespeicherte Medianwerte, Perzentilgrenzen und Skalierung wurden unabhängig aus den jeweiligen Trainingszeilen nachgerechnet; geladene Modelle reproduzieren die gespeicherten Vorwärtsprognosen. Weder die Aktienzielrendite noch verspätete Bestandteile ihres Benchmarkziels überschreiten innere oder äußere Trainingsgrenzen. Nachrichten-Eingangszeiten, Kursstichtage, Zielhorizonte, identische Prognosezeilen und Quellhashes wurden geprüft. Zehn absolute Vierwochenbewegungen über 50 % im Gesamtpanel wurden dokumentiert, nicht nachträglich entfernt. Das sind Implementierungsprüfungen, keine Garantie vollständig unverzerrter Quelldaten.')
p('Verbleibend: nur 100 historische Großkonzerne, dünne wöchentliche 15-Minuten-Nachrichtenstichproben, schwache firmenspezifische Textzuordnung, Übersetzungsfehler, aktuelle Kursanpassungen/Revisionen, fehlende Fundamental-Vintages und bereits bekannte frühere Testjahre. Die hohe Zeilenzahl ist keine entsprechende Zahl unabhängiger Marktereignisse: Im Test sind es 195 Kalenderwochen. Die Modellierung behandelt dieses Abhängigkeitsproblem mit gemeinsamen Wochenblöcken, behebt aber nicht sämtliche Auswahl- oder Datenprobleme.')
p('Der Versuch liefert keine gesicherten „essenziellen Faktoren für Kursanstiege“. Er zeigt, welche Merkmale gemeinsam variieren, und prüft tatsächlich, ob deren damalige Zustände spätere Mehrerträge vorhersagen. Für diese Messungen und Verfahren bleibt der praktische Zusatznutzen unbewiesen. Die App und ihre Strategien wurden nicht geändert.')
p('Paketinhalt: Bericht als selbständige HTML-Datei und Markdown, drei Abbildungen, Python-Skripte, Original-Kurs-/Devisensnapshots und kompakte Nachrichtenmetadaten, gemeinsame Eingabematrix, jedes Jahresmodell, Vorwärtsprognosen, Ladungen, Weglassdiagnosen, innere Parameterauswahl, Kostenvergleich sowie Zeit-/Quellprüfungen. requirements.txt hält Paketversionen fest. README.md beschreibt die Wiederholung; Quellen und Grenzen stehen zusätzlich in sources.md. Originalmodelle und ursprüngliche Resultate bleiben für die Nachprüfung unverändert neben den ausdrücklich gekennzeichneten Darstellungsdiagnosen erhalten.')
